import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic schema compilation', () => {
  it('caches dynamic schemas by object reference specs/hal-engine-tool-input-validation/spec.md#8', async () => {
    const registry = new ToolRegistry();
    const compile = jest.spyOn(registry['ajv'], 'compile');
    const first = {type: 'object', properties: {location: {type: 'string'}}};
    const second = {type: 'object', properties: {location: {type: 'number'}}};
    let schema = first;
    registry.register(() => ({name: 'dynamic', description: 'Dynamic', inputSchema: schema}), async () => 'ok');

    await registry.execute('dynamic', {});
    await registry.execute('dynamic', {});
    schema = second;
    await registry.execute('dynamic', {});
    schema = first;
    await registry.execute('dynamic', {});

    expect(compile).toHaveBeenCalledTimes(2);
    expect(compile).toHaveBeenNthCalledWith(1, first);
    expect(compile).toHaveBeenNthCalledWith(2, second);
  });
});
